import {readFileSync, writeFileSync, mkdirSync} from 'node:fs';
import {join, resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {instrumentTypeScriptWithCoverage} from '../scripts/run-istanbul-bun-coverage';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
import {sourceHash} from '../scripts/quality-inventory';
const root=process.cwd(),storage=createOwnedTestDirectory('memory-json-measure-');
const paths=['tests/helpers/capture-json.ts','tests/helpers/capture-json.test.ts'];
try {
 mkdirSync(join(storage.dir,'tests/helpers'),{recursive:true});
 for(const path of paths){
  const built=instrumentTypeScriptWithCoverage(readFileSync(path,'utf8'),resolve(path));
  writeFileSync(join(storage.dir,path),built.code);
 }
 writeFileSync(join(storage.dir,'tests/helpers/owned-test-directory.ts'),readFileSync('tests/helpers/owned-test-directory.ts'));
 writeFileSync(join(storage.dir,'capture.ts'),'import {afterAll} from "bun:test"; import {writeFileSync} from "node:fs"; afterAll(()=>writeFileSync("coverage.json",JSON.stringify((globalThis as any).__coverage__)));');
 writeFileSync(join(storage.dir,'bunfig.toml'),'[test]\ncoverage = false\npreload = ['+JSON.stringify(join(root,'tests/test-setup.ts'))+', "./capture.ts"]\n');
 const result=Bun.spawnSync([process.execPath,'test','--timeout','15000','tests/helpers/capture-json.test.ts'],{cwd:storage.dir,env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:45000});
 const output=new TextDecoder().decode(result.stdout)+new TextDecoder().decode(result.stderr);
 if(result.exitCode!==0)throw Error(output);
 const raw=JSON.parse(readFileSync(join(storage.dir,'coverage.json'),'utf8')),map=createCoverageMap(raw);
 const files=paths.map(path=>{
  const measured=map.fileCoverageFor(resolve(path)),data=measured.data;
  return {path,sourceHash:sourceHash(readFileSync(path,'utf8')),metrics:measured.toSummary().data,
   uncoveredBranches:Object.entries(data.b).flatMap(([id,hits])=>hits.flatMap((count,index)=>count===0?[{id,index,location:data.branchMap[id]?.locations[index]}]:[])),
   uncoveredFunctions:Object.entries(data.f).filter(([,hits])=>hits===0).map(([id])=>data.fnMap[id])};
 });
 writeFileSync('.git/b11-json-measure.json',JSON.stringify({scope:'Local diagnostic; B05 instrumenter acceptance and independent review remain open. No package/native acceptance.',recordedAt:new Date().toISOString(),runtime:Bun.version,files,rawCoverage:raw,output,probeSource:readFileSync('.git/b11-json-measure.ts','utf8')},null,2)+'\n');
 console.log(JSON.stringify(files));
} finally {storage.cleanup();}

