import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {join} from 'node:path';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
import {sourceHash} from '../scripts/quality-inventory';
const root=process.cwd(),path='tests/helpers/capture-json.ts',source=readFileSync(path,'utf8');
const faults=[
 {id:'omit-ownership-registration',from:'owned.add(storage);',to:'/* omitted registration */'},
 {id:'skip-nonempty-cleanup',from:'if (pending.length === 0) return;',to:'if (pending.length !== 0) return;'},
 {id:'skip-owned-removal',from:'storage.cleanup();',to:'/* omitted cleanup */'},
 {id:'forget-failed-capability',from:'} catch (cause) {',to:'} catch (cause) { owned.delete(storage);'},
 {id:'swallow-cleanup-failures',from:'if (failures.length > 0) {',to:'if (false) {'},
 {id:'consume-later-allocations',from:'for (const storage of pending) {',to:'for (const storage of owned) {'},
 {id:'drop-underlying-cause',from:'{ cause }',to:'{}'},
 {id:'bypass-ownership-check',from:'storage.cleanup();',to:'require("node:fs").rmSync(storage.dir, {recursive:true,force:true});'},
];
const results:unknown[]=[];
for(const fault of faults){
 if(source.split(fault.from).length!==2)throw Error('Nonunique fault seam '+fault.id);
 const storage=createOwnedTestDirectory('memory-json-fault-');
 try {
  mkdirSync(join(storage.dir,'tests/helpers'),{recursive:true});
  writeFileSync(join(storage.dir,path),source.replace(fault.from,fault.to));
  for(const file of ['capture-json.test.ts','owned-test-directory.ts'])writeFileSync(join(storage.dir,'tests/helpers',file),readFileSync(join(root,'tests/helpers',file)));
  writeFileSync(join(storage.dir,'bunfig.toml'),'[test]\ncoverage = false\npreload = ['+JSON.stringify(join(root,'tests/test-setup.ts'))+']\n');
  const run=Bun.spawnSync([process.execPath,'test','--timeout','15000','tests/helpers/capture-json.test.ts'],{cwd:storage.dir,env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:30000});
  const output=new TextDecoder().decode(run.stdout)+new TextDecoder().decode(run.stderr);
  const detected=run.exitCode!==0 && /\(fail\) capture-json test helpers/.test(output) && /\d+ fail/.test(output) && !run.signalCode;
  results.push({...fault,detected,exit:run.exitCode,signal:run.signalCode,output});
  writeFileSync('.git/b11-json-faults.json',JSON.stringify({recordedAt:new Date().toISOString(),sourceHash:sourceHash(source),testHash:sourceHash(readFileSync('tests/helpers/capture-json.test.ts','utf8')),runtime:Bun.version,scope:'Local cleanup decision fault checks, not exhaustive mutation or final review.',results,probeSource:readFileSync('.git/b11-json-faults.ts','utf8')},null,2)+'\n');
  console.log(JSON.stringify({id:fault.id,detected,exit:run.exitCode}));
  if(!detected)throw Error('Fault not detected by completed assertions');
 }finally{storage.cleanup();}
}

