const sources=['tests/helpers/capture-json.ts','tests/helpers/capture-json.test.ts','tests/helpers/owned-test-directory.ts',...commands.map(c=>`src/presentation/cli/commands/${c}.json.test.ts`)];
const checks:unknown[]=[];
async function run(args:string[]) {
 const child=Bun.spawn([process.execPath,...args],{cwd:root,stdout:'pipe',stderr:'pipe'});
 const [exit,stdout,stderr]=await Promise.all([child.exited,new Response(child.stdout).text(),new Response(child.stderr).text()]);
 const result={command:[process.execPath,...args],exit,stdout,stderr};checks.push(result);
 writeFileSync('.git/b11-json-check.json',JSON.stringify({recordedAt:new Date().toISOString(),runtime:Bun.version,checks,sourceInputs:sources.map(path=>({path,sourceHash:sourceHash(readFileSync(path,'utf8'))}))},null,2)+'\n');
 console.log(JSON.stringify({args,exit,summary:(stdout+stderr).slice(-350)}));
 if(exit!==0)throw Error('Check failed');
}
writeFileSync('.git/b11-json-tsconfig.json',JSON.stringify({extends:'../tsconfig.json',compilerOptions:{rootDir:'..',noEmit:true},include:sources.map(path=>'../'+path),exclude:[]},null,2));
await run(['run','typecheck']);
await run(['node_modules/typescript/bin/tsc','-p','.git/b11-json-tsconfig.json']);
const storage=createOwnedTestDirectory('memory-json-build-');
try {
 const out=join(storage.dir,'declarations');mkdirSync(out);
 await run(['node_modules/typescript/bin/tsc','-p','tsconfig.lib.json','--outDir',out]);
 const testOnly=existsSync(join(out,'presentation/cli/commands/_helpers/capture-json.d.ts'));
 if(testOnly || !existsSync(join(out,'index.d.ts')))throw Error('Wrong declaration boundary');
 console.log('Declaration output contains library entrypoint and no test-only capture helper.');
}finally{storage.cleanup();}
await run(['run','test','tests/helpers/capture-json.test.ts',...commands.map(c=>`src/presentation/cli/commands/${c}.json.test.ts`)]);

import {readFileSync, writeFileSync, mkdirSync} from 'node:fs';
import {join, resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {instrumentTypeScriptWithCoverage} from '../scripts/run-istanbul-bun-coverage';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
import {sourceHash} from '../scripts/quality-inventory';
const root=process.cwd(),storage=createOwnedTestDirectory('memory-json-measure-');
const paths=['tests/helpers/capture-json.ts','tests/helpers/capture-json.test.ts'];
try {
 mkdirSync(join(storage.dir,'tests/helpers'),{recursive:true});
 for(const path of paths){
  const built=instrumentTypeScriptWithCoverage(readFileSync(path,'utf8'),resolve(path));
  writeFileSync(join(storage.dir,path),built.code);
 }
 writeFileSync(join(storage.dir,'tests/helpers/owned-test-directory.ts'),readFileSync('tests/helpers/owned-test-directory.ts'));
 writeFileSync(join(storage.dir,'capture.ts'),'import {afterAll} from "bun:test"; import {writeFileSync} from "node:fs"; afterAll(()=>writeFileSync("coverage.json",JSON.stringify((globalThis as any).__coverage__)));');
 writeFileSync(join(storage.dir,'bunfig.toml'),'[test]\ncoverage = false\npreload = ['+JSON.stringify(join(root,'tests/test-setup.ts'))+', "./capture.ts"]\n');
 const result=Bun.spawnSync([process.execPath,'test','--timeout','15000','tests/helpers/capture-json.test.ts'],{cwd:storage.dir,env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:45000});
 const output=new TextDecoder().decode(result.stdout)+new TextDecoder().decode(result.stderr);
 if(result.exitCode!==0)throw Error(output);
 const raw=JSON.parse(readFileSync(join(storage.dir,'coverage.json'),'utf8')),map=createCoverageMap(raw);
 const files=paths.map(path=>{
  const measured=map.fileCoverageFor(resolve(path)),data=measured.data;
  return {path,sourceHash:sourceHash(readFileSync(path,'utf8')),metrics:measured.toSummary().data,
   uncoveredBranches:Object.entries(data.b).flatMap(([id,hits])=>hits.flatMap((count,index)=>count===0?[{id,index,location:data.branchMap[id]?.locations[index]}]:[])),
   uncoveredFunctions:Object.entries(data.f).filter(([,hits])=>hits===0).map(([id])=>data.fnMap[id])};
 });
 writeFileSync('.git/b11-json-measure.json',JSON.stringify({scope:'Local diagnostic; B05 instrumenter acceptance and independent review remain open. No package/native acceptance.',recordedAt:new Date().toISOString(),runtime:Bun.version,files,rawCoverage:raw,output,probeSource:readFileSync('.git/b11-json-measure.ts','utf8')},null,2)+'\n');
 console.log(JSON.stringify(files));
} finally {storage.cleanup();}

import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {join} from 'node:path';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
import {sourceHash} from '../scripts/quality-inventory';
const root=process.cwd(),path='tests/helpers/capture-json.ts',source=readFileSync(path,'utf8');
const faults=[
 {id:'omit-ownership-registration',from:'owned.add(storage);',to:'/* omitted registration */'},
 {id:'skip-nonempty-cleanup',from:'if (pending.length === 0) return;',to:'if (pending.length !== 0) return;'},
 {id:'skip-owned-removal',from:'storage.cleanup();',to:'/* omitted cleanup */'},
 {id:'forget-failed-capability',from:'} catch (cause) {',to:'} catch (cause) { owned.delete(storage);'},
 {id:'swallow-cleanup-failures',from:'if (failures.length > 0) {',to:'if (false) {'},
 {id:'consume-later-allocations',from:'for (const storage of pending) {',to:'for (const storage of owned) {'},
 {id:'drop-underlying-cause',from:'{ cause }',to:'{}'},
 {id:'bypass-ownership-check',from:'storage.cleanup();',to:'require("node:fs").rmSync(storage.dir, {recursive:true,force:true});'},
];
const results:unknown[]=[];
for(const fault of faults){
 if(source.split(fault.from).length!==2)throw Error('Nonunique fault seam '+fault.id);
 const storage=createOwnedTestDirectory('memory-json-fault-');
 try {
  mkdirSync(join(storage.dir,'tests/helpers'),{recursive:true});
  writeFileSync(join(storage.dir,path),source.replace(fault.from,fault.to));
  for(const file of ['capture-json.test.ts','owned-test-directory.ts'])writeFileSync(join(storage.dir,'tests/helpers',file),readFileSync(join(root,'tests/helpers',file)));
  writeFileSync(join(storage.dir,'bunfig.toml'),'[test]\ncoverage = false\npreload = ['+JSON.stringify(join(root,'tests/test-setup.ts'))+']\n');
  const run=Bun.spawnSync([process.execPath,'test','--timeout','15000','tests/helpers/capture-json.test.ts'],{cwd:storage.dir,env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:30000});
  const output=new TextDecoder().decode(run.stdout)+new TextDecoder().decode(run.stderr);
  const detected=run.exitCode!==0 && /\(fail\) capture-json test helpers/.test(output) && /\d+ fail/.test(output) && !run.signalCode;
  results.push({...fault,detected,exit:run.exitCode,signal:run.signalCode,output});
  writeFileSync('.git/b11-json-faults.json',JSON.stringify({recordedAt:new Date().toISOString(),sourceHash:sourceHash(source),testHash:sourceHash(readFileSync('tests/helpers/capture-json.test.ts','utf8')),runtime:Bun.version,scope:'Local cleanup decision fault checks, not exhaustive mutation or final review.',results,probeSource:readFileSync('.git/b11-json-faults.ts','utf8')},null,2)+'\n');
  console.log(JSON.stringify({id:fault.id,detected,exit:run.exitCode}));
  if(!detected)throw Error('Fault not detected by completed assertions');
 }finally{storage.cleanup();}
}

import {mkdirSync,readFileSync,writeFileSync} from 'node:fs';
import {join} from 'node:path';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
const root=process.cwd(),storage=createOwnedTestDirectory('memory-json-teardown-');
try {
 mkdirSync(join(storage.dir,'tests/helpers'),{recursive:true});
 for(const file of ['capture-json.ts','owned-test-directory.ts'])writeFileSync(join(storage.dir,'tests/helpers',file),readFileSync(join(root,'tests/helpers',file)));
 const driver=`import {it,expect,afterEach,afterAll} from 'bun:test';
import {captureStreams,createTempDatabaseTracker} from './tests/helpers/capture-json';
import {createOwnedTestDirectory} from './tests/helpers/owned-test-directory';
import {rmSync,existsSync} from 'node:fs';
import {dirname} from 'node:path';
let locked=true;
const paths:string[]=[];
const tracker=createTempDatabaseTracker(prefix=>createOwnedTestDirectory(prefix,{remove(path){if(locked)throw Error('B114_CLEANUP_FAILURE');rmSync(path,{recursive:true,force:false});}}));
afterEach(()=>tracker.cleanup());
afterAll(async()=>{locked=false;await tracker.cleanup();for(const path of paths)expect(existsSync(dirname(path))).toBe(false);});
it('retains primary and teardown failures',async()=>{paths.push(tracker.makePath('combined'));await captureStreams(async()=>{throw Error('B114_PRIMARY_FAILURE');});});
it('next test preserves the failed fixture and retries it',()=>{expect(existsSync(dirname(paths[0]!))).toBe(true);paths.push(tracker.makePath('later'));expect(paths[0]).not.toBe(paths[1]);locked=false;});
`;
 writeFileSync(join(storage.dir,'combined.test.ts'),driver);
 writeFileSync(join(storage.dir,'bunfig.toml'),'[test]\ncoverage = false\npreload = ['+JSON.stringify(join(root,'tests/test-setup.ts'))+']\n');
 const result=Bun.spawnSync([process.execPath,'test','--timeout','15000','combined.test.ts'],{cwd:storage.dir,env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:30000});
 const output=new TextDecoder().decode(result.stdout)+new TextDecoder().decode(result.stderr);
 const verified=result.exitCode===1 && !result.signalCode && output.includes('error: B114_PRIMARY_FAILURE') && output.includes('error: B114_CLEANUP_FAILURE') && output.includes('JSON test storage retained:') && output.includes('(pass) next test preserves the failed fixture and retries it') && output.includes('1 pass') && output.includes('1 fail');
 writeFileSync('.git/b11-json-teardown.json',JSON.stringify({recordedAt:new Date().toISOString(),runtime:Bun.version,verified,exit:result.exitCode,signal:result.signalCode,output,driver,scope:'Actual Bun lifecycle: command and afterEach failures are both observable; next test uses the same tracker, unlocks and retries both independent fixtures. afterAll checks both are removed.'},null,2)+'\n');
 console.log(JSON.stringify({verified,exit:result.exitCode,output}));
 if(!verified)throw Error('Combined failure proof incomplete');
}finally{storage.cleanup();}
